#pragma once

#include "prelude.h"

// tsc's libMap (generated by lib_names.py): every name `lib` and `/// <reference lib>` take, in its order (the order
// error messages list them in and the program orders the library files by, getDefaultLibFilePriority)
extern char const* const lib_names[];
extern u32 const lib_name_count;
// The names whose file isn't lib.NAME.d.ts: { name, the file's NAME }
extern char const* const lib_aliases[][2];
extern u32 const lib_alias_count;
// tsc's optionDeclarations, in its order (the order getSpellingSuggestion sees them in): commonOptionsWithBuild (the
// first tsc_common_options_with_build), then optionsForCompiler
extern char const* const tsc_option_names[];
extern u32 const tsc_option_names_count;
extern u32 const tsc_common_options_with_build;
// `build` and what tsc's optionsForBuild adds to commonOptionsWithBuild
extern char const* const tsc_build_only_option_names[];
extern u32 const tsc_build_only_option_names_count;
// Each option's kind, one letter per tsc_option_names entry (tsgo's CommandLineOptionType: b boolean, s string,
// n number, e enum, l list, L listOrElement, o object), and the kind of the elements of the list options:
// { name, letter } (commandLineOptionElements)
extern char const tsc_option_kinds[];
extern char const* const tsc_option_elements[][2];
extern u32 const tsc_option_elements_count;
